using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using MarketSphere.Domain.Entities.Infrastructure;
namespace MarketSphere.Infrastructure.Persistence.Configurations.Infrastructure;
public sealed class ApprovalPolicyConfiguration : IEntityTypeConfiguration<ApprovalPolicy> { public void Configure(EntityTypeBuilder<ApprovalPolicy> builder) { builder.ToTable("ApprovalPolicies", t => { t.HasCheckConstraint("CK_ApprovalPolicies_AmountRange", "[MaximumAmount] IS NULL OR [MinimumAmount] IS NULL OR [MaximumAmount] >= [MinimumAmount]"); t.HasCheckConstraint("CK_ApprovalPolicies_DiscountRange", "[MaximumDiscountPercent] IS NULL OR [MinimumDiscountPercent] IS NULL OR [MaximumDiscountPercent] >= [MinimumDiscountPercent]"); t.HasCheckConstraint("CK_ApprovalPolicies_Period", "[EffectiveTo] IS NULL OR [EffectiveTo] >= [EffectiveFrom]"); }); builder.HasKey(x => x.ApprovalPolicyID); builder.Property(x => x.ApprovalType).HasConversion<int>(); builder.Property(x => x.EntityType).HasMaxLength(100).IsRequired(); builder.Property(x => x.Channel).HasConversion<int>(); builder.Property(x => x.MinimumAmount).HasPrecision(18, 2); builder.Property(x => x.MaximumAmount).HasPrecision(18, 2); builder.Property(x => x.MinimumDiscountPercent).HasPrecision(9, 4); builder.Property(x => x.MaximumDiscountPercent).HasPrecision(9, 4); builder.HasIndex(x => new { x.ApprovalType, x.EntityType, x.IsActive, x.Priority }); builder.HasOne(x => x.Branch).WithMany().HasForeignKey(x => x.BranchID).OnDelete(DeleteBehavior.Restrict); } }
